// Writes tools/athletes/build/rig.json from the game's rig (src/game/world/character/rig.ts), so the
// Blender scripts conform and skin every asset to exactly the skeleton the runtime animates.
// Run with: node --experimental-strip-types tools/athletes/export-rig.ts
import { mkdirSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { ARM_A, B, BONE_COUNT, LEG_A, OFFSETS, PARENT, bindPose, bindRotation } from '../../src/game/world/character/rig.ts'

const here = path.dirname(fileURLToPath(import.meta.url))
const out = path.join(here, 'build', 'rig.json')

const names: string[] = []
for (const [name, i] of Object.entries(B)) names[i] = name
if (names.length !== BONE_COUNT || names.some((n) => !n)) throw new Error('rig: bone table is not dense')

const bp = bindPose()
const r6 = (v: number) => Math.round(v * 1e6) / 1e6
const rig = {
  $comment: 'Generated by tools/athletes/export-rig.ts from src/game/world/character/rig.ts. Normalized units (height = 1), three.js axes (Y up, +Z forward), A-pose bind.',
  units: 'normalized-height',
  eulerOrder: 'XYZ',
  armA: ARM_A,
  legA: LEG_A,
  bones: names.map((name, i) => ({
    index: i,
    name,
    parent: PARENT[i] >= 0 ? names[PARENT[i]] : null,
    offset: OFFSETS[i].map(r6),
    bindEuler: bindRotation(i).map(r6),
    bindPos: bp.pos[i].map(r6),
    // column-major 4x4 (three.js Matrix4.elements) of the bone's bind-pose world matrix
    bindMatrix: bp.mat[i].elements.map(r6),
  })),
}
mkdirSync(path.dirname(out), { recursive: true })
writeFileSync(out, JSON.stringify(rig, null, 2) + '\n')
console.log(`[rig] ${names.length} bones -> ${path.relative(process.cwd(), out)}`)
